<?php
declare(strict_types=1);

namespace App\Controllers\Admin;

use App\Middleware\AdminAuthMiddleware;
use App\Services\Admin\AdminAuthorizationService;
use App\Services\Admin\AdminInstrumentService;
use PDOException;
use RuntimeException;
use Throwable;

final class AdminInstrumentsController
{
    public function __construct(private readonly AdminAuthorizationService $authz=new AdminAuthorizationService()){}
    public function index():void{$admin=$this->authz->requirePermission('instruments.view');try{$data=(new AdminInstrumentService())->listInstruments($_GET);$this->page($admin,'Instruments','admin/instruments/index',$data,'instruments');}catch(Throwable $e){$this->failure($e,'instrument list');}}
    public function createForm():void{$admin=$this->authz->requirePermission('instruments.manage');$service=new AdminInstrumentService();$this->page($admin,'Create Instrument','admin/instruments/form',['instrument'=>null,'categories'=>$service->categories(),'create'=>true],'instruments');}
    public function create():void{$admin=$this->authz->requirePermission('instruments.manage');if(!$this->csrfFailure())return;try{$id=(new AdminInstrumentService())->createInstrument((int)$admin['id'],$_POST);$_SESSION['_flash']['admin_info']='Demo instrument created and initialized.';\redirect('admin/instruments/'.$id);}catch(Throwable $e){$this->mutationFailure($e,'instrument create','admin/instruments/create');}}
    public function show(string $reference):void{$admin=$this->authz->requirePermission('instruments.view');$id=filter_var($reference,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($id===false){$this->notFound();return;}try{$data=(new AdminInstrumentService())->getInstrument((int)$id);if(!$data){$this->notFound();return;}$this->page($admin,'Instrument · '.$data['symbol'],'admin/instruments/show',['instrument'=>$data,'categories'=>$data['categories']??[],'activity'=>$data['activity']??[]],'instruments');}catch(Throwable $e){$this->failure($e,'instrument detail');}}
    public function update(string $reference):void{$admin=$this->authz->requirePermission('instruments.manage');if(!$this->csrfFailure())return;$id=filter_var($reference,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($id===false){$this->notFound();return;}try{$result=(new AdminInstrumentService())->updateInstrument((int)$id,(int)$admin['id'],$_POST);$_SESSION['_flash']['admin_info']='Instrument configuration saved.';\redirect('admin/instruments/'.$id);}catch(Throwable $e){$this->mutationFailure($e,'instrument update','admin/instruments/'.$id);}}
    public function categories():void{$admin=$this->authz->requirePermission('instruments.manage');try{$service=new AdminInstrumentService();$this->page($admin,'Instrument Categories','admin/instruments/categories',['categories'=>$service->categories()],'instruments');}catch(Throwable $e){$this->failure($e,'instrument categories');}}
    public function updateCategory(string $reference):void{$admin=$this->authz->requirePermission('instruments.manage');if(!$this->csrfFailure())return;$id=filter_var($reference,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($id===false){$this->notFound();return;}try{(new AdminInstrumentService())->updateCategory((int)$id,(int)$admin['id'],$_POST);$_SESSION['_flash']['admin_info']='Instrument category updated.';\redirect('admin/instruments/categories');}catch(Throwable $e){$this->mutationFailure($e,'instrument category update','admin/instruments/categories');}}
    public function resetMarketState(string $reference):void{$admin=$this->authz->requirePermission('instruments.manage');$this->authz->requirePermission('trading.manage');if(!$this->csrfFailure())return;$id=filter_var($reference,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($id===false){$this->notFound();return;}try{(new AdminInstrumentService())->resetMarketState((int)$id,(int)$admin['id'],is_string($_POST['reason']??null)?$_POST['reason']:'',is_string($_POST['confirmation']??null)?$_POST['confirmation']:'');$_SESSION['_flash']['admin_info']='Demo market state reset and reinitialized.';\redirect('admin/instruments/'.$id);}catch(Throwable $e){$this->mutationFailure($e,'Demo market reset','admin/instruments/'.$id);}}

    private function page(array $admin,string $title,string $view,array $data,string $active):void{AdminAuthMiddleware::headers();$permissions=$this->authz->permissions((int)$admin['id']);\render('admin/layout/layout',['title'=>$title.' · MultiForex Administration','pageTitle'=>$title,'admin'=>$admin,'permissions'=>$permissions,'adminData'=>['role_permissions'=>$permissions]+$data,'contentView'=>$view,'activeRoute'=>$active,'csrfToken'=>\generate_admin_csrf_token(),'notice'=>\flash_get('admin_info'),'error'=>\flash_get('admin_error')]);}
    private function csrfFailure():bool{if(\verify_admin_csrf_token(is_string($_POST['_admin_csrf']??null)?$_POST['_admin_csrf']:null))return true;AdminAuthMiddleware::headers();http_response_code(403);\render('admin/error-page',['title'=>'Request could not be verified','status'=>403,'message'=>'Refresh the administration page and try again.','loginUrl'=>\admin_url('login')]);return false;}
    private function notFound():void{AdminAuthMiddleware::headers();http_response_code(404);\render('admin/error-page',['title'=>'Not found','status'=>404,'message'=>'Instrument was not found.','loginUrl'=>\admin_url('login')]);}
    private function failure(Throwable $e,string $context):void{error_log('Admin '.$context.' could not be loaded: '.get_class($e));AdminAuthMiddleware::headers();http_response_code(503);\render('admin/error-page',['title'=>'Page temporarily unavailable','status'=>503,'message'=>'This administration data could not be loaded. Please try again shortly.','loginUrl'=>\admin_url('login')]);}
    private function mutationFailure(Throwable $e,string $context,string $fallback):void{$code=(int)$e->getCode();$status=$e instanceof PDOException?503:($e instanceof RuntimeException?($code===404?404:($code===409?409:422)):500);$message=in_array($status,[404,409,422],true)?$e->getMessage():'This request could not be completed. Please try again shortly.';if($status!==422)error_log('Admin '.$context.' action failed: '.get_class($e));$_SESSION['_flash']['admin_error']=$message;\redirect($fallback);}
}
